# traffic: a Moore machine, generated by Silinx from the state diagram traffic.fsm.json (edit the drawing, not this file).
# MicroPython for the ESP32 DevKit. One tick every TICK_MS milliseconds: the inputs read once at its start, the outputs
# written to their pins at its end (Silinx's synchronous reactive model: docs/SYSTEMS.md).
# Inputs: req GPIO4, done GPIO13, night GPIO14.
# Outputs: phase GPIO16 GPIO17 GPIO18.
# (a port of several bits: its pins bit 0 first)

from machine import Pin
import time

# ---- the pins
PIN_REQ = Pin(4, Pin.IN)
PIN_DONE = Pin(13, Pin.IN)
PIN_NIGHT = Pin(14, Pin.IN)
PIN_PHASE = (Pin(16, Pin.OUT), Pin(17, Pin.OUT), Pin(18, Pin.OUT))

TICK_MS = 10  # the tick's period

# ---- the states
S_CARS = 0  # cars green, pedestrians red (at least 5 s)
S_CARS_YELLOW = 1  # cars yellow (2 s)
S_ALL_RED = 2  # all red (1 s): the crossing clears
S_WALK = 3  # pedestrians green (5 s)
S_WALK_END = 4  # pedestrian green blinking (3 s): hurry up
S_ALL_RED_2 = 5  # all red (1 s)
S_NIGHT = 6  # night: cars flashing yellow, pedestrian lamps off

# ---- the inputs, read once per tick
req = 0
done = 0
night = 0

# ---- the outputs
phase = 0  # 3 bits

# ---- the memory
state = S_CARS


# a number to its pins, bit 0 first
def write_bits(pins, v):
    for i in range(len(pins)):
        pins[i].value((v >> i) & 1)


def read_inputs():
    global req, done, night
    req = PIN_REQ.value()
    done = PIN_DONE.value()
    night = PIN_NIGHT.value()


def write_outputs():
    write_bits(PIN_PHASE, phase)


# the reset state
def reset_machine():
    global state
    state = S_CARS


# one tick: the outputs of the present state and of the inputs, then the next state
def step_machine():
    global state, phase
    read_inputs()
    # the outputs' defaults
    phase = 0
    if state == S_CARS:
        phase = 0
        if night:
            state = S_NIGHT
        elif not night and req and done:
            state = S_CARS_YELLOW
    elif state == S_CARS_YELLOW:
        phase = 1
        if done:
            state = S_ALL_RED
    elif state == S_ALL_RED:
        phase = 2
        if done:
            state = S_WALK
    elif state == S_WALK:
        phase = 3
        if done:
            state = S_WALK_END
    elif state == S_WALK_END:
        phase = 4
        if done:
            state = S_ALL_RED_2
    elif state == S_ALL_RED_2:
        phase = 5
        if done:
            state = S_CARS
    elif state == S_NIGHT:
        phase = 6
        if not night:
            state = S_CARS
    write_outputs()


# the reset state, then a tick every TICK_MS milliseconds
def main():
    reset_machine()
    last = time.ticks_ms()
    while True:
        if time.ticks_diff(time.ticks_ms(), last) >= TICK_MS:
            last = time.ticks_add(last, TICK_MS)
            step_machine()


main()
